INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Komputer Makin Lambat Membuka File$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Komputer yang dulu cepat membuka file lama-kelamaan terasa lambat: aplikasi butuh waktu lama untuk terbuka, file besar seperti video tersendat saat diputar, dan hardisk berbunyi sibuk terus-menerus. Salah satu penyebab umum pada hardisk mekanis (HDD) adalah fragmentasi — data sebuah file tersebar di banyak lokasi berbeda sehingga jarum baca hardisk harus berpindah-pindah untuk membacanya.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Apa Itu Fragmentasi Hardisk?$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Hardisk mekanis menyimpan data di piringan magnetik yang berputar. Saat file dihapus dan ditulis berulang kali, ruang kosong yang tersisa menjadi terpecah-pecah. File baru yang disimpan akan dipotong-potong mengikuti ruang kosong itu — inilah fragmentasi. Defragmentasi adalah proses menyusun ulang potongan-potongan file agar berdekatan kembali, sehingga pembacaan menjadi lebih cepat dan efisien.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Alat yang Dibutuhkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Komputer Windows dengan hardisk mekanis (HDD) — bukan SSD$txt$, $txt$Akses administrator pada akun Windows$txt$, $txt$Waktu luang 30 menit hingga beberapa jam (tergantung ukuran hardisk)$txt$, $txt$Colokan listrik / charger terpasang (jangan defrag saat baterai lemah)$txt$, $txt$Cadangan (backup) data penting, sebagai jaga-jaga$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah: Cara Defragment Hardisk di Windows$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Tutup semua aplikasi yang sedang berjalan agar proses tidak terganggu.$txt$, $txt$Buka File Explorer, klik kanan drive (misalnya C:), pilih Properties.$txt$, $txt$Masuk ke tab Tools, lalu klik tombol Optimize di bagian Optimize and defragment drive.$txt$, $txt$Pilih drive HDD yang ingin dioptimalkan, lalu klik Analyze untuk melihat tingkat fragmentasi.$txt$, $txt$Jika fragmentasi di atas 10%, klik Optimize dan tunggu hingga selesai — jangan matikan komputer selama proses.$txt$, $txt$Setelah selesai, tutup jendela dan restart komputer untuk merasakan perbedaannya.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Hal yang Perlu Diperhatikan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$JANGAN defragment SSD (Solid State Drive) — SSD tidak punya piringan bergerak sehingga tidak butuh defrag, malah umurnya bisa berkurang.$txt$, $txt$Proses defrag pada hardisk yang hampir penuh (>90%) berjalan sangat lambat; kosongkan dulu sebagian file.$txt$, $txt$Jika hardisk berbunyi aneh (klik/berderit) saat defrag, hentikan dan periksa kesehatan hardisk — bisa jadi tanda kerusakan fisik.$txt$, $txt$Jangan mematikan komputer secara paksa saat defrag berjalan; tunggu hingga selesai.$txt$, $txt$Defrag bukan solusi untuk semua kelambatan — virus, RAM penuh, atau hardisk rusak butuh penanganan berbeda.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Pemeriksaan Hasil dan Tindak Lanjut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Buka kembali Optimize Drives — status drive seharusnya tertulis OK (0% fragmented).$txt$, $txt$Uji buka aplikasi dan file besar: waktu muat seharusnya lebih singkat dari sebelumnya.$txt$, $txt$Jadwalkan defrag otomatis: di jendela Optimize Drives klik Change settings lalu aktifkan jadwal mingguan.$txt$, $txt$Jika tetap lambat setelah defrag, pertimbangkan upgrade ke SSD atau tambah RAM sebagai langkah berikutnya.$txt$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Pergelangan Kaki Terkilir Saat Beraktivitas$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Kaki terkilir (ankle sprain) adalah cedera yang sangat umum — terjadi saat bermain bola, lari, turun tangga, atau sekadar salah injak. Pergelangan kaki langsung bengkak, nyeri saat dipijak, dan kadang memar. Penanganan yang tepat di jam-jam pertama sangat menentukan kecepatan pemulihan dan mencegah cedera berulang.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Apa yang Terjadi Saat Kaki Terkilir?$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Terkilir terjadi ketika ligamen — jaringan kuat yang menghubungkan tulang di sendi — meregang berlebihan atau robek sebagian akibat gerakan memutar yang tiba-tiba. Tingkat keparahannya bertingkat: ringan (ligamen meregang), sedang (robek sebagian), dan berat (robek total atau disertai patah tulang). Sebagian besar kasus ringan-sedang bisa ditangani di rumah dengan metode yang tepat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Persiapan: Alat Pertolongan Pertama$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Es batu atau kompres dingin (bungkus dengan handuk tipis, jangan tempel langsung)$txt$, $txt$Perban elastis untuk membalut$txt$, $txt$Bantal untuk mengganjal kaki lebih tinggi dari jantung$txt$, $txt$Obat pereda nyeri bebas seperti parasetamol (ikuti aturan pakai)$txt$, $txt$Tongkat atau penyangga bila sulit berjalan$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah: Metode RICE untuk Kaki Terkilir$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Rest (istirahat): hentikan aktivitas, jangan paksakan berjalan atau berolahraga dengan kaki yang terkilir.$txt$, $txt$Ice (es): tempelkan kompres dingin 15–20 menit setiap 2–3 jam selama 1–2 hari pertama untuk mengurangi bengkak.$txt$, $txt$Compression (kompresi): balut pergelangan kaki dengan perban elastis — cukup kencang menopang, tidak sampai kesemutan atau kebas.$txt$, $txt$Elevation (elevasi): ganjal kaki dengan bantal agar posisinya lebih tinggi dari jantung, terutama saat berbaring.$txt$, $txt$Setelah 2–3 hari, bila bengkak berkurang, kompres hangat boleh digunakan untuk melancarkan peredaran darah.$txt$, $txt$Lakukan gerakan ringan pergelangan kaki (melingkar perlahan) setelah nyeri berkurang untuk mencegah kaku.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Tanda Bahaya: Kapan ke Dokter?$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Segera ke dokter atau IGD bila: tidak bisa menapak sama sekali, kaki berubah bentuk, nyeri sangat hebat, atau mati rasa.$txt$, $txt$Waspada bila bengkak tidak membaik setelah 3–4 hari atau justru memburuk.$txt$, $txt$Jangan memijat area yang terkilir di 48 jam pertama — bisa memperparah pembengkakan.$txt$, $txt$Jangan mengoleskan balsam panas atau minyak panas di fase awal pembengkakan.$txt$, $txt$Artikel ini bersifat informasi umum dan BUKAN pengganti nasihat medis — bila ragu, konsultasikan ke dokter atau fasilitas kesehatan terdekat.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Pemeriksaan Hasil dan Pemulihan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Terkilir ringan umumnya membaik dalam 1–2 minggu; sedang bisa 4–6 minggu — bersabarlah dan jangan terburu-buru berolahraga berat.$txt$, $txt$Latih kembali kekuatan pergelangan kaki dengan berdiri satu kaki setelah nyeri hilang untuk mencegah terkilir berulang.$txt$, $txt$Gunakan sepatu yang menopang pergelangan kaki dengan baik saat beraktivitas.$txt$, $txt$Bila kaki terkilir berulang di sisi yang sama, konsultasikan ke dokter — bisa jadi ligamennya sudah longgar dan butuh fisioterapi.$txt$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Suku Bugis: Pelaut Ulung Nusantara$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Suku Bugis berasal dari Sulawesi Selatan dan dikenal sebagai salah satu suku pelaut terhebat di Nusantara. Sejak berabad-abad lalu, para pelaut Bugis berlayar hingga ke Malaka, Filipina, bahkan Australia utara untuk berdagang. Keberanian dan keahlian navigasi mereka diabadikan dalam kapal legendaris bernama pinisi.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Pinisi: Kapal Legendaris Tanpa Paku$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Pinisi adalah kapal layar tradisional suku Bugis-Makassar yang dibuat dengan teknik pasak kayu — tanpa satu pun paku besi. Papan-papan lambung kapal disambung dengan pasak kayu dan diikat sedemikian rupa sehingga lentur mengikuti ombak. Teknik ini terbukti tangguh menghadapi ganasnya laut Indonesia selama ratusan tahun.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Teknik Pembuatan: Warisan Turun-Temurun$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Pembuatan pinisi dipimpin oleh seorang punggawa (ahli kapal) dan dikerjakan secara gotong royong di pusat-pusat pembuatan kapal seperti Tana Beru, Bulukumba. Kayu terbaik seperti kayu ulin atau jati dipilih, dibentuk, lalu disusun mulai dari lunas hingga lambung. Seluruh pengetahuan ini diwariskan secara lisan dari generasi ke generasi, tanpa gambar teknik modern.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Filosofi dan Ritual dalam Pembuatan Kapal$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Bagi masyarakat Bugis, membuat kapal bukan sekadar pekerjaan tukang — ia sarat ritual dan filosofi. Ada doa dan sesaji pada tahap-tahap penting seperti peletakan lunas dan peluncuran kapal. Kapal dianggap memiliki roh dan harus diperlakukan dengan hormat; pantangan-pantangan tertentu dijaga selama proses pembuatan agar kapal selamat di lautan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Pinisi di Era Modern$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Kini pinisi tidak hanya dipakai untuk berdagang, tetapi juga menjadi kapal wisata mewah yang berlayar di perairan Indonesia timur seperti Labuan Bajo dan Raja Ampat. Pada tahun 2017, UNESCO menetapkan seni pembuatan kapal pinisi sebagai Warisan Budaya Takbenda dunia — pengakuan bahwa kearifan suku Bugis adalah kekayaan seluruh umat manusia.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Kobalt: Logam Biru yang Serbaguna$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Kobalt adalah unsur logam dengan simbol Co dan nomor atom 27. Ia memiliki warna keperakan dengan semburat kebiruan yang khas. Meski namanya kurang populer dibanding besi atau emas, kobalt memegang peran penting dalam teknologi modern — dari baterai ponsel hingga mesin jet.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Sifat-sifat Kobalt$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kobalt adalah logam keras, tahan panas, dan bersifat magnetik — salah satu dari sedikit unsur yang bisa menjadi magnet permanen alami bersama besi dan nikel. Ia tidak mudah berkarat dan tetap kuat pada suhu sangat tinggi, sehingga ideal untuk paduan logam (alloy) khusus seperti baja perkakas dan komponen turbin pesawat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Kobalt dalam Baterai dan Teknologi Modern$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Peran kobalt paling terkenal saat ini adalah sebagai bahan katoda baterai lithium-ion — baterai yang dipakai ponsel, laptop, dan mobil listrik. Kobalt membantu baterai menyimpan lebih banyak energi dan lebih stabil. Inilah alasan permintaan kobalt melonjak seiring berkembangnya kendaraan listrik di seluruh dunia.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Pigmen Biru Kobalt dalam Seni$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Jauh sebelum era baterai, kobalt sudah terkenal sebagai pewarna. Senyawa kobalt menghasilkan warna biru yang sangat pekat dan tahan lama — biru kobalt. Pigmen ini dipakai dalam keramik, kaca, dan lukisan sejak ribuan tahun lalu, termasuk keramik biru-putih khas Tiongkok dan kaca patri gereja-gereja Eropa.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Manfaat, Risiko, dan Masa Depan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Kobalt juga dibutuhkan tubuh dalam jumlah sangat kecil sebagai bagian dari vitamin B12. Namun dalam jumlah besar, debu dan senyawa kobalt bisa berbahaya bagi paru-paru dan kulit, sehingga penambangan dan pengolahannya harus mengikuti standar keselamatan. Para ilmuwan kini meneliti baterai dengan kobalt lebih sedikit demi rantai pasok yang lebih adil dan ramah lingkungan.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah mempelajari materi ini, kamu diharapkan mampu: (1) menjelaskan latar belakang lahirnya Orde Baru, (2) mengidentifikasi kebijakan-kebijakan pembangunan pada masa Orde Baru, (3) menganalisis dampak positif dan negatif Orde Baru, serta (4) menjelaskan faktor-faktor berakhirnya Orde Baru.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Latar Belakang Lahirnya Orde Baru$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Orde Baru lahir setelah peristiwa Gerakan 30 September 1965. Ketidakstabilan politik dan ekonomi pada akhir masa Orde Lama — seperti inflasi yang sangat tinggi dan konflik politik — membuka jalan bagi Mayjen Soeharto yang kemudian mengeluarkan Surat Perintah 11 Maret 1966 (Supersemar). Sejak itu kekuasaan berangsur beralih, dan Soeharto diangkat menjadi Presiden pada tahun 1968, menandai dimulainya era Orde Baru.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Kebijakan Pembangunan Orde Baru$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Fokus utama Orde Baru adalah pembangunan ekonomi melalui Rencana Pembangunan Lima Tahun (Repelita). Pemerintah membuka keran investasi asing, menstabilkan harga kebutuhan pokok, dan membangun infrastruktur besar-besaran. Di bidang pertanian, program Bimas dan Inmas mendorong swasembada beras yang tercapai pada tahun 1984. Stabilitas politik dijaga ketat demi kelancaran pembangunan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Dampak Positif dan Negatif$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Positif: pertumbuhan ekonomi rata-rata sekitar 7% per tahun selama tiga dekade, kemiskinan menurun, infrastruktur dan pendidikan meluas.$txt$, $txt$Positif: swasembada beras 1984 dan program KB yang menekan laju pertumbuhan penduduk.$txt$, $txt$Negatif: kekuasaan terpusat dan sangat lama (32 tahun) sehingga kritik sulit disuarakan.$txt$, $txt$Negatif: praktik korupsi, kolusi, dan nepotisme (KKN) merajalela di berbagai level pemerintahan.$txt$, $txt$Negatif: kebebasan pers dan berpendapat dibatasi; perbedaan pendapat politik sering dihadapi dengan tindakan represif.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Berakhirnya Orde Baru$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Krisis moneter Asia yang melanda Indonesia sejak pertengahan 1997 memicu krisis ekonomi hebat: nilai rupiah anjlok, harga-harga melonjak, dan banyak perusahaan bangkrut. Ketidakpuasan masyarakat memuncak dalam gerakan reformasi yang dipelopori mahasiswa. Setelah kerusuhan besar Mei 1998, Presiden Soeharto mengundurkan diri pada 21 Mei 1998 dan digantikan B.J. Habibie — menandai berakhirnya Orde Baru dan dimulainya era Reformasi.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan Soal$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$1. Jelaskan latar belakang lahirnya Orde Baru! (Kunci: peristiwa G30S 1965, Supersemar 11 Maret 1966, pengangkatan Soeharto sebagai presiden 1968.)$txt$, $txt$2. Sebutkan dua kebijakan pembangunan ekonomi pada masa Orde Baru beserta hasilnya! (Kunci: Repelita — pertumbuhan ekonomi; program Bimas/Inmas — swasembada beras 1984.)$txt$, $txt$3. Mengapa Orde Baru berakhir pada tahun 1998? Jelaskan! (Kunci: krisis moneter 1997–1998, gerakan reformasi mahasiswa, pengunduran diri Soeharto 21 Mei 1998.)$txt$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah belajar materi ini, kamu diharapkan bisa: (1) menjelaskan pengertian kecepatan dengan bahasamu sendiri, (2) menghitung kecepatan jika jarak dan waktu diketahui, (3) menghitung jarak dan waktu dari kecepatan, serta (4) menyelesaikan soal cerita tentang kecepatan dalam kehidupan sehari-hari.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Pengertian Kecepatan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kecepatan adalah seberapa jauh suatu benda berpindah dalam waktu tertentu. Misalnya, sepeda motor yang melaju 60 kilometer dalam 1 jam berarti kecepatannya 60 kilometer per jam (ditulis 60 km/jam). Rumus kecepatan adalah: kecepatan = jarak : waktu. Ingat segitiga ajaibnya: Jarak di atas, Kecepatan dan Waktu di bawah — tutup yang ditanya, itulah rumusnya!$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Contoh Soal Terpecahkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Contoh 1: Ayah mengendarai mobil sejauh 120 km dalam waktu 2 jam. Berapa kecepatan mobil ayah? Jawab: kecepatan = jarak : waktu = 120 : 2 = 60 km/jam. Contoh 2: Sebuah bus melaju dengan kecepatan 50 km/jam selama 3 jam. Berapa jarak yang ditempuh? Jawab: jarak = kecepatan × waktu = 50 × 3 = 150 km.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Menghitung Jarak dari Kecepatan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Kalau kecepatan dan waktunya sudah diketahui, jarak bisa dicari dengan perkalian: jarak = kecepatan × waktu. Contoh: Siti bersepeda dengan kecepatan 15 km/jam selama 2 jam. Jarak yang ditempuh Siti = 15 × 2 = 30 km. Perhatikan satuannya ya — kalau kecepatan dalam km/jam dan waktu dalam jam, hasilnya dalam km.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Menghitung Waktu dari Kecepatan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Sebaliknya, kalau jarak dan kecepatannya diketahui, waktu bisa dicari dengan pembagian: waktu = jarak : kecepatan. Contoh: Jarak rumah Budi ke sekolah 6 km, ia berjalan kaki dengan kecepatan 3 km/jam. Waktu yang dibutuhkan = 6 : 3 = 2 jam. Jadi Budi harus berangkat 2 jam sebelum bel masuk!$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan Soal$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$1. Sebuah kereta menempuh jarak 240 km dalam waktu 4 jam. Berapa kecepatan kereta tersebut? (Kunci: 240 : 4 = 60 km/jam.)$txt$, $txt$2. Rudi berlari dengan kecepatan 8 km/jam selama 30 menit (0,5 jam). Berapa jarak yang ditempuh Rudi? (Kunci: 8 × 0,5 = 4 km.)$txt$, $txt$3. Jarak kota A ke kota B adalah 180 km. Sebuah mobil melaju dengan kecepatan 60 km/jam. Berapa lama perjalanan mobil itu? (Kunci: 180 : 60 = 3 jam.)$txt$])));
